from math import sqrt, log, erf

def normal_cdf(x):
    return (1+erf(x/sqrt(2)))/2

def gaussian_tv(vin, vout):
    cross=sqrt(vin*vout*log(vout/vin)/(vout-vin))
    return abs(2*(normal_cdf(cross/sqrt(vin))-normal_cdf(cross/sqrt(vout))))
print('Corollary 5 check: IN variance 1')
for vout in (4.,2.):
    print('OUT variance',vout,'optimal LR advantage',gaussian_tv(1.,vout))
